import java.util.logging.*;

// Runnable demo: present organized, verified company research for the interview.
public class ResearchDemo {
    private static final Logger log = Logger.getLogger("Research");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        CompanyDossier dossier = new CompanyDossier("National Bank of India", List.of(
            new ResearchFact("BUSINESS", "Retail + corporate bank; revenue from payments and lending", true),
            new ResearchFact("PRODUCT", "UPI consumer app + corporate bulk-settlement portal", true),
            new ResearchFact("TECHNOLOGY", "Java + Spring backend, Kafka event streaming", true),
            new ResearchFact("NEWS", "Recently launched instant international remittance", true),
            new ResearchFact("TEAM", "This team owns the fraud detection platform", true),
            new ResearchFact("TECHNOLOGY", "Settlement reconciliation internals (could not verify)", false)));

        ResearchPresenter presenter = new ResearchPresenter(log);
        presenter.present(dossier);
    }
}
