package com.bank.research.model;

// A single researched fact, tagged by category and whether it is verified.
public class ResearchFact {
    private final String category;   // BUSINESS, PRODUCT, TECHNOLOGY, NEWS, TEAM
    private final String detail;
    private final boolean verified;

    public ResearchFact(String category, String detail, boolean verified) {
        this.category = category;
        this.detail = detail;
        this.verified = verified;
    }

    public String getCategory() { return category; }
    public String getDetail() { return detail; }
    public boolean isVerified() { return verified; }
}
