package com.bank.research.service;

import com.bank.research.model.CompanyDossier;
import com.bank.research.model.ResearchFact;
import java.util.List;
import java.util.logging.*;

// Presents research in a fixed, logical order; flags unverified facts honestly.
public class ResearchPresenter {
    private final Logger log;

    // The deliberate order: broad business down to the specific team.
    private static final List<String> ORDER =
        List.of("BUSINESS", "PRODUCT", "TECHNOLOGY", "NEWS", "TEAM");

    public ResearchPresenter(Logger log) { this.log = log; }

    public void present(CompanyDossier dossier) {
        log.info(() -> "Research on " + dossier.getCompanyName() + ":");
        for (String category : ORDER) {
            dossier.getFacts().stream()
                .filter(f -> f.getCategory().equals(category))
                .forEach(this::emit);
        }
    }

    private void emit(ResearchFact f) {
        if (f.isVerified()) {
            log.info(() -> "   [" + f.getCategory() + "] " + f.getDetail());
        } else {
            // Never assert an unverified fact — frame it as curiosity.
            log.warning(() -> "   [" + f.getCategory() + "] UNVERIFIED — ask about: "
                + f.getDetail());
        }
    }
}
